<template>
  <q-page class="payments-page">
    <main class="payments-shell">
      <header class="page-header"><h1 class="sr-only">Payments</h1><p>{{ pendingVerification.length }} {{ pendingVerification.length === 1 ? 'payment' : 'payments' }} awaiting verification · {{ formatPeso(outstandingAmount) }} outstanding</p></header>
      <section class="controls" aria-label="Find and filter payments">
        <label class="sr-only" for="payment-search">Search payments</label>
        <div class="search-control"><IconifyIcon icon="lucide:search" width="19" aria-hidden="true" /><input id="payment-search" v-model="searchText" type="search" placeholder="Search tenants or properties" autocomplete="off" /><button v-if="searchText" type="button" aria-label="Clear search" @click="searchText = ''"><IconifyIcon icon="lucide:x" width="18" aria-hidden="true" /></button></div>
        <nav class="filter-bar" aria-label="Payment status filters"><button v-for="filter in filters" :key="filter.value" type="button" :class="{ active: statusFilter === filter.value }" :aria-pressed="statusFilter === filter.value" @click="statusFilter = filter.value">{{ filter.label }}</button></nav>
      </section>

      <section v-if="loading" class="surface loading-list" aria-busy="true"><div v-for="index in 5" :key="index" class="skeleton-row" /><span class="sr-only">Loading payments</span></section>
      <section v-else-if="error" class="surface state-panel state-panel--error" role="alert"><span class="state-icon"><IconifyIcon icon="lucide:cloud-alert" width="24" aria-hidden="true" /></span><h2>Unable to load payments</h2><p>{{ error }}</p><button type="button" class="primary-action" @click="loadPayments"><IconifyIcon icon="lucide:refresh-cw" width="17" aria-hidden="true" /> Retry</button></section>

      <template v-else>
        <section v-if="visiblePendingVerification.length" class="payment-section" aria-labelledby="verification-heading"><div class="section-heading"><div><h2 id="verification-heading">Verify submitted payments</h2><p>Review proof before marking a payment as received.</p></div><span>{{ visiblePendingVerification.length }}</span></div><div class="surface payment-list"><article v-for="payment in visiblePendingVerification" :key="payment.id" class="payment-row"><span class="payment-icon payment-icon--warning"><IconifyIcon icon="lucide:file-check-2" width="19" aria-hidden="true" /></span><div class="payment-copy"><strong>{{ payment.studentName }}</strong><span>{{ payment.propertyName }} · {{ payment.roomName }}</span><small>{{ formatMonth(payment.month) }} · {{ methodLabel(payment.method) }}<template v-if="payment.txnReference"> · {{ payment.txnReference }}</template></small></div><div class="payment-side"><strong>{{ formatPeso(payment.amount) }}</strong><a v-if="payment.proofUrl" :href="payment.proofUrl" target="_blank" rel="noopener">View proof</a><span v-else>No proof attached</span><button type="button" :disabled="verifyingId === payment.id" @click="verifyPayment(payment)"><IconifyIcon icon="lucide:check" width="15" aria-hidden="true" /> {{ verifyingId === payment.id ? 'Verifying' : 'Confirm' }}</button></div></article></div></section>

        <section v-if="visibleOutstanding.length" class="payment-section" aria-labelledby="outstanding-heading"><div class="section-heading"><div><h2 id="outstanding-heading">Collection queue</h2><p>Payments that remain due or overdue.</p></div><span>{{ visibleOutstanding.length }}</span></div><div class="surface payment-list"><article v-for="payment in visibleOutstanding" :key="payment.id" class="payment-row"><span class="payment-icon" :class="payment.status === 'overdue' ? 'payment-icon--danger' : 'payment-icon--neutral'"><IconifyIcon :icon="payment.status === 'overdue' ? 'lucide:circle-alert' : 'lucide:receipt-text'" width="19" aria-hidden="true" /></span><div class="payment-copy"><strong>{{ payment.studentName }}</strong><span>{{ payment.propertyName }} · {{ payment.roomName }}</span><small>{{ formatMonth(payment.month) }} · {{ methodLabel(payment.method) }}</small></div><div class="payment-side"><strong>{{ formatPeso(payment.amount) }}</strong><span class="status-badge" :class="`status-badge--${toneForStatus(payment.status)}`">{{ statusLabel(payment.status) }}</span></div></article></div></section>

        <section v-if="visiblePaid.length" class="payment-section" aria-labelledby="paid-heading"><div class="section-heading"><div><h2 id="paid-heading">Received payments</h2><p>Confirmed payment history.</p></div><span>{{ visiblePaid.length }}</span></div><div class="surface payment-list"><article v-for="payment in visiblePaid" :key="payment.id" class="payment-row"><span class="payment-icon payment-icon--success"><IconifyIcon icon="lucide:circle-check" width="19" aria-hidden="true" /></span><div class="payment-copy"><strong>{{ payment.studentName }}</strong><span>{{ payment.propertyName }} · {{ payment.roomName }}</span><small>{{ payment.paidAt ? formatDate(payment.paidAt) : formatMonth(payment.month) }} · {{ methodLabel(payment.method) }}</small></div><div class="payment-side"><strong>{{ formatPeso(payment.amount) }}</strong><span class="status-badge status-badge--success">Paid</span></div></article></div></section>

        <EmptyState v-if="!visiblePayments.length" icon="lucide:receipt-text" :title="payments.length ? 'No matching payments' : 'No payments yet'" :message="payments.length ? 'Try another search or payment-status filter.' : 'Payment records for tenants in your properties will appear here.'"><button v-if="payments.length" type="button" class="secondary-action" @click="clearFilters">Clear filters</button></EmptyState>
      </template>
    </main>
  </q-page>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Icon as IconifyIcon } from '@iconify/vue'
import { useQuasar } from 'quasar'
import { useRouter } from 'vue-router'
import { supabase } from '@/shared/utils/supabase'
import { formatPeso } from '@/shared/utils/format'
import EmptyState from '@/components/shared/EmptyState.vue'

type PaymentFilter = 'all' | 'pending_verification' | 'outstanding' | 'paid'
interface Payment { id: string; leaseId: string; amount: number; method: string; month: string; status: string; paidAt: string | null; proofUrl: string | null; txnReference: string | null; studentName: string; propertyName: string; roomName: string }
const $q = useQuasar(); const router = useRouter(); const loading = ref(true); const error = ref<string | null>(null); const payments = ref<Payment[]>([]); const searchText = ref(''); const statusFilter = ref<PaymentFilter>('all'); const verifyingId = ref<string | null>(null)
const filters: { label: string; value: PaymentFilter }[] = [{ label: 'All', value: 'all' }, { label: 'To verify', value: 'pending_verification' }, { label: 'Outstanding', value: 'outstanding' }, { label: 'Paid', value: 'paid' }]
const filteredPayments = computed(() => { const term = searchText.value.trim().toLowerCase(); return payments.value.filter((payment) => { const matchesSearch = !term || [payment.studentName, payment.propertyName, payment.roomName].some((value) => value.toLowerCase().includes(term)); const matchesFilter = statusFilter.value === 'all' || (statusFilter.value === 'pending_verification' && payment.status === 'pending_verification') || (statusFilter.value === 'outstanding' && ['due', 'overdue'].includes(payment.status)) || (statusFilter.value === 'paid' && payment.status === 'paid'); return matchesSearch && matchesFilter }) })
const pendingVerification = computed(() => payments.value.filter((payment) => payment.status === 'pending_verification'))
const outstandingAmount = computed(() => payments.value.filter((payment) => ['due', 'overdue'].includes(payment.status)).reduce((total, payment) => total + payment.amount, 0))
const visiblePayments = computed(() => filteredPayments.value); const visiblePendingVerification = computed(() => filteredPayments.value.filter((payment) => payment.status === 'pending_verification')); const visibleOutstanding = computed(() => filteredPayments.value.filter((payment) => ['due', 'overdue'].includes(payment.status))); const visiblePaid = computed(() => filteredPayments.value.filter((payment) => payment.status === 'paid'))
function formatMonth(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Payment month unavailable' : date.toLocaleDateString('en-PH', { month: 'long', year: 'numeric' }) }
function formatDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Date unavailable' : date.toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) }
function methodLabel(method: string) { return (method || 'Method unavailable').replace(/_/g, ' ').replace(/\b\w/g, (character) => character.toUpperCase()) }
function statusLabel(status: string) { return status === 'overdue' ? 'Overdue' : status === 'due' ? 'Due' : status === 'pending_verification' ? 'Pending review' : 'Paid' }
function toneForStatus(status: string) { return status === 'overdue' ? 'danger' : status === 'due' || status === 'pending_verification' ? 'warning' : 'success' }
async function loadPayments() {
  loading.value = true; error.value = null
  try {
    const { data: { user }, error: userError } = await supabase.auth.getUser()
    if (userError) throw userError
    if (!user) { void router.push('/login'); return }
    const { data: accRows, error: accError } = await (supabase as any).from('accommodations').select('id, name, business_name').eq('accommodation_manager_id', user.id)
    if (accError) throw accError
    const accs: any[] = (accRows ?? []) as any[]
    const accById = new Map<string, any>(accs.map((item) => [item.id, item]))
    const ids: string[] = accs.map((item) => item.id)
    const { data: roomRows, error: roomError } = ids.length ? await (supabase as any).from('rooms').select('id, accommodation_id, room_number, label').in('accommodation_id', ids) : { data: [], error: null }
    if (roomError) throw roomError
    const rooms: any[] = (roomRows ?? []) as any[]
    const roomById = new Map<string, any>(rooms.map((item) => [item.id, item]))
    const roomIds: string[] = rooms.map((item) => item.id)
    const { data: leaseRows, error: leaseError } = roomIds.length ? await (supabase as any).from('leases').select('id, student_id, room_id').in('room_id', roomIds) : { data: [], error: null }
    if (leaseError) throw leaseError
    const leases: any[] = (leaseRows ?? []) as any[]; const leaseById = new Map<string, any>(leases.map((item) => [item.id, item])); const leaseIds: string[] = leases.map((item) => item.id)
    const { data: paymentRows, error: paymentError } = leaseIds.length ? await (supabase as any).from('payments').select('id, lease_id, amount, method, month, status, paid_at, proof_url, txn_reference').in('lease_id', leaseIds) : { data: [], error: null }
    if (paymentError) throw paymentError
    const studentIds: string[] = Array.from(new Set<string>(leases.map((item) => item.student_id).filter(Boolean)))
    const { data: userRows, error: usersError } = studentIds.length ? await supabase.from('users').select('id, full_name').in('id', studentIds) : { data: [], error: null }
    if (usersError) throw usersError
    const names = new Map<string, string>((userRows ?? []).map((item: any) => [item.id, item.full_name || '']))
    payments.value = ((paymentRows ?? []) as any[]).map((payment) => {
      const lease = leaseById.get(payment.lease_id); const room = lease ? roomById.get(lease.room_id) : null; const property = room ? accById.get(room.accommodation_id) : null
      return { id: payment.id, leaseId: payment.lease_id, amount: Number(payment.amount || 0), method: payment.method || '', month: payment.month || '', status: payment.status || 'due', paidAt: payment.paid_at, proofUrl: payment.proof_url, txnReference: payment.txn_reference, studentName: names.get(lease?.student_id) || 'Tenant', propertyName: property?.business_name || property?.name || 'Unassigned property', roomName: room?.label || (room?.room_number ? `Room ${room.room_number}` : 'Unassigned room') }
    }).sort((a, b) => new Date(b.paidAt || b.month).getTime() - new Date(a.paidAt || a.month).getTime())
  } catch (reason) { error.value = reason instanceof Error ? reason.message : 'We could not retrieve payment records.' } finally { loading.value = false }
}
async function verifyPayment(payment: Payment) { verifyingId.value = payment.id; const priorStatus = payment.status; payment.status = 'paid'; payment.paidAt = new Date().toISOString(); try { const { data: { user } } = await supabase.auth.getUser(); if (!user) throw new Error('Please sign in again.'); const { error: updateError } = await (supabase as any).from('payments').update({ status: 'paid', paid_at: payment.paidAt, verified_by: user.id }).eq('id', payment.id); if (updateError) throw updateError; $q.notify({ type: 'positive', message: 'Payment confirmed as received.', position: 'top' }) } catch (reason) { payment.status = priorStatus; payment.paidAt = null; $q.notify({ type: 'negative', message: reason instanceof Error ? reason.message : 'Unable to verify payment.', position: 'top' }) } finally { verifyingId.value = null } }
function clearFilters() { searchText.value = ''; statusFilter.value = 'all' }
onMounted(() => { void loadPayments() })
</script>

<style scoped>
.payments-page { min-height: 100%; background: var(--m-bg); color: var(--m-text); }.payments-shell { width: 100%; max-width: 760px; margin: 0 auto; padding: max(var(--m-space-3), env(safe-area-inset-top)) var(--m-page-gutter) max(112px, calc(var(--m-space-8) + env(safe-area-inset-bottom))); }.page-header { margin-bottom: 16px; }.page-header p { margin: 0; color: var(--m-muted); font-size: 13px; font-weight: 700; }.controls { display: grid; gap: 10px; margin-bottom: 20px; }.search-control { display: flex; min-height: 46px; align-items: center; gap: 10px; padding: 0 12px; border: 1px solid var(--m-border); border-radius: 8px; background: var(--m-surface); color: var(--m-muted); }.search-control input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--m-ink); font: inherit; }.search-control button { display: grid; min-width: 32px; min-height: 32px; place-items: center; border: 0; background: transparent; color: var(--m-primary-dark); }.filter-bar { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; }.filter-bar button { min-height: 36px; flex: 0 0 auto; padding: 0 12px; border: 1px solid var(--m-border); border-radius: 999px; background: var(--m-surface); color: var(--m-text); font-size: 12px; font-weight: 750; }.filter-bar button.active { border-color: var(--m-primary); background: var(--m-primary-soft); color: var(--m-primary-dark); }.payment-section { display: grid; gap: 10px; margin-bottom: 24px; }.section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }.section-heading h2,.state-panel h2 { margin: 0; color: var(--m-ink); font-size: 18px; font-weight: 800; line-height: 1.25; }.section-heading p { margin: 3px 0 0; color: var(--m-muted); font-size: 12px; line-height: 1.4; }.section-heading > span { min-width: 24px; padding: 3px 7px; border-radius: 999px; background: var(--m-bg); color: var(--m-muted); font-size: 11px; font-weight: 800; text-align: center; }.surface { overflow: hidden; border: 1px solid var(--m-border); border-radius: 12px; background: var(--m-surface); }.payment-row { display: grid; min-height: 88px; grid-template-columns: 40px minmax(0,1fr) auto; align-items: center; gap: 12px; padding: 12px; border-bottom: 1px solid var(--m-border); }.payment-row:last-child { border-bottom: 0; }.payment-icon,.state-icon { display: grid; width: 40px; height: 40px; place-items: center; border-radius: 10px; }.payment-icon--warning { background: var(--m-warning-soft); color: var(--m-warning); }.payment-icon--danger,.state-panel--error .state-icon { background: var(--m-danger-soft); color: var(--m-danger); }.payment-icon--success { background: var(--m-success-soft); color: var(--m-success); }.payment-icon--neutral,.state-icon { background: var(--m-bg); color: var(--m-text); }.payment-copy { display: grid; min-width: 0; gap: 2px; }.payment-copy strong { overflow: hidden; color: var(--m-ink); font-size: 14px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }.payment-copy span,.payment-copy small { overflow: hidden; color: var(--m-muted); font-size: 11px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }.payment-side { display: grid; justify-items: end; gap: 5px; padding-left: 4px; }.payment-side > strong { color: var(--m-ink); font-size: 13px; font-weight: 800; white-space: nowrap; }.payment-side a,.payment-side > span { color: var(--m-primary-dark); font-size: 10px; font-weight: 750; }.payment-side > span { color: var(--m-muted); }.payment-side button { min-height: 30px; padding: 0 9px; border: 0; border-radius: 7px; background: var(--m-primary-dark); color: #fff; font-size: 11px; font-weight: 800; }.payment-side button svg { margin-right: 4px; vertical-align: -2px; }.payment-side button:disabled { opacity: .6; }.status-badge { min-height: 23px; padding: 4px 7px; border-radius: 999px; font-size: 10px; font-weight: 800; }.status-badge--success { background: var(--m-success-soft); color: var(--m-success); }.status-badge--warning { background: var(--m-warning-soft); color: var(--m-warning); }.status-badge--danger { background: var(--m-danger-soft); color: var(--m-danger); }.state-panel { display: flex; min-height: 280px; flex-direction: column; align-items: flex-start; justify-content: center; padding: 24px; }.state-icon { margin-bottom: 16px; }.state-panel p { margin: 8px 0 20px; color: var(--m-muted); font-size: 13px; line-height: 1.5; }.primary-action,.secondary-action { min-height: 44px; padding: 0 16px; border-radius: 8px; font-size: 13px; font-weight: 800; }.primary-action { border: 0; background: var(--m-primary-dark); color: #fff; }.primary-action svg { margin-right: 7px; vertical-align: -3px; }.secondary-action { border: 1px solid var(--m-border); background: var(--m-surface); color: var(--m-primary-dark); }.loading-list { padding: 0 12px; }.skeleton-row { height: 88px; border-bottom: 1px solid var(--m-border); background: linear-gradient(90deg, transparent 0 15%, #edf0f2 15% 55%, transparent 55% 60%, #edf0f2 60% 100%); animation: shimmer 1.4s ease infinite; }.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; } @keyframes shimmer { 50% { opacity: .5; } } @media (max-width: 390px) { .payment-row { grid-template-columns: 40px minmax(0,1fr); }.payment-side { grid-column: 2; justify-items: start; grid-auto-flow: column; justify-content: start; align-items: center; }.payment-side button { margin-left: 4px; } }
</style>
